class Solution {
    long long palindrome(long long half,bool odd){
        long long result=half,value=odd?half/10:half;
        while(value){
            result=result*10+value%10;
            value/=10;
        }
        return result;
    }
    bool basePalindrome(long long value,int k){
        vector<int> digits;
        while(value){
            digits.push_back(value%k);
            value/=k;
        }
        return equal(digits.begin(),digits.begin()+digits.size()/2,digits.rbegin());
    }
    public: long long kMirror(int k,int n){
        long long answer=0;
        for(int length=1;;++length){
            int halfLength=(length+1)/2;
            long long start=1;
            for(int i=1;i<halfLength;++i)start*=10;
            for(long long half=start;half<start*10;++half){
                long long value=palindrome(half,length%2);
                if(basePalindrome(value,k)){
                    answer+=value;
                    if(!--n)return answer;
                }
            }
        }
    }
};
